import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

import {
  Screen,
  EmptyState,
} from "../components/common/UI";

import "../styles/Orders.css";

export default function Orders() {
  const navigate = useNavigate();
  const [orders, setOrders] = useState([]);
  const [filter, setFilter] = useState("All");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // TODO: Replace with actual API call to GET /orders
    // Query: status (comma-separated list), page, limit
    setOrders([
      {
        _id: "1",
        public_id: "GR-98312",
        merchant: {
          _id: "1",
          business_name: "SupaMart Grocers"
        },
        created_at: "2026-10-18T10:24:00.000Z",
        item_count: 3,
        total: { kes: "564.00", aud: "6.24" },
        status: "preparing",
        status_label: "Being Fulfilled",
        my_role: "payer"
      },
      {
        _id: "2",
        public_id: "GR-98311",
        merchant: {
          _id: "1",
          business_name: "SupaMart Grocers"
        },
        created_at: "2026-10-17T14:30:00.000Z",
        item_count: 2,
        total: { kes: "400.00", aud: "4.43" },
        status: "received",
        status_label: "Received",
        my_role: "payer"
      },
      {
        _id: "3",
        public_id: "GR-98310",
        merchant: {
          _id: "2",
          business_name: "Fresh Market"
        },
        created_at: "2026-10-15T09:15:00.000Z",
        item_count: 1,
        total: { kes: "180.00", aud: "1.99" },
        status: "cancelled",
        status_label: "Cancelled",
        my_role: "payer"
      }
    ]);
    setLoading(false);
  }, []);

  const filteredOrders =
    filter === "All"
      ? orders
      : orders.filter(
          (order) => order.status === filter
        );

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffTime = Math.abs(now - date);
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays === 0) {
      return "Today";
    } else if (diffDays === 1) {
      return "Yesterday";
    } else {
      return date.toLocaleDateString("en-US", { month: "short", day: "numeric" });
    }
  };

  if (loading) {
    return <Screen title="My Orders">Loading...</Screen>;
  }

  return (
    <Screen title="My Orders">
      <div className="row between" style={{ marginBottom: "16px" }}>
        <h3 className="card-title" style={{ margin: 0 }}>
          Active & Past Orders
        </h3>
        <span className="muted small">{orders.length} Total</span>
      </div>

      <div className="order-filters">
        {[
          "All",
          "payment_requested",
          "paid",
          "preparing",
          "ready",
          "received",
          "cancelled",
        ].map((item) => (
          <button
            key={item}
            className={
              filter === item ? "active" : ""
            }
            onClick={() => setFilter(item)}
          >
            {item === "payment_requested" ? "Pending" : 
             item === "paid" ? "Paid" :
             item === "preparing" ? "Preparing" :
             item === "ready" ? "Ready" :
             item.charAt(0).toUpperCase() + item.slice(1)}
          </button>
        ))}
      </div>

      {filteredOrders.length > 0 ? (
        <div className="orders-list">
          {filteredOrders.map((order) => (
            <button
              key={order._id}
              className="panel order-card"
              onClick={() =>
                navigate(`/orders/${order._id}`)
              }
            >
              <div className="row between">
                <strong>{order.public_id}</strong>

                <span
                  className={`status ${order.status}`}
                >
                  {order.status_label}
                </span>
              </div>

              <p>{order.merchant.business_name}</p>

              <div className="row between muted small">
                <span>{formatDate(order.created_at)}</span>

                <b className="orange">
                  KSh {order.total.kes}
                </b>
              </div>
            </button>
          ))}
        </div>
      ) : (
        <EmptyState
          icon="📦"
          title="No orders found"
          description="Your orders will appear here."
          action="Browse Merchants"
          onAction={() => navigate("/home")}
        />
      )}
    </Screen>
  );
}
